-- LEFT JOIN on purpose: recipe 11 uses INNER JOIN, which silently drops a company whose SIC code is missing from
-- the reference (IBM 3570). Here such a company stays, with NULL hierarchy columns.
CREATE SCHEMASTORE VIEW company_profile WITH CONTAINER edgar AS
SELECT
    s.cik AS cik,
    s.ticker AS ticker,
    s.entity_name AS entity_name,
    s.sic_code AS sic_code,
    s.sic_description_edgar AS sic_description_edgar,
    s.state_of_incorporation AS state_of_incorporation,
    r.description AS sic_description_reference,
    r.division AS division,
    r.division_desc AS division_desc,
    r.major_group AS major_group,
    r.major_group_desc AS major_group_desc,
    r.industry_group AS industry_group,
    r.industry_group_desc AS industry_group_desc
FROM (
    SELECT cik, 'WMT' AS ticker, name AS entity_name, sic AS sic_code, `sicDescription` AS sic_description_edgar, `stateOfIncorporation` AS state_of_incorporation FROM sec_data.walmart_submissions_raw
    UNION ALL
    SELECT cik, 'TGT' AS ticker, name AS entity_name, sic AS sic_code, `sicDescription` AS sic_description_edgar, `stateOfIncorporation` AS state_of_incorporation FROM sec_data.target_submissions_raw
    UNION ALL
    SELECT cik, 'COST' AS ticker, name AS entity_name, sic AS sic_code, `sicDescription` AS sic_description_edgar, `stateOfIncorporation` AS state_of_incorporation FROM sec_data.costco_submissions_raw
    UNION ALL
    SELECT cik, 'KR' AS ticker, name AS entity_name, sic AS sic_code, `sicDescription` AS sic_description_edgar, `stateOfIncorporation` AS state_of_incorporation FROM sec_data.kroger_submissions_raw
    UNION ALL
    SELECT cik, 'DG' AS ticker, name AS entity_name, sic AS sic_code, `sicDescription` AS sic_description_edgar, `stateOfIncorporation` AS state_of_incorporation FROM sec_data.dollar_general_submissions_raw
    UNION ALL
    SELECT cik, 'BBY' AS ticker, name AS entity_name, sic AS sic_code, `sicDescription` AS sic_description_edgar, `stateOfIncorporation` AS state_of_incorporation FROM sec_data.best_buy_submissions_raw
    UNION ALL
    SELECT cik, 'F' AS ticker, name AS entity_name, sic AS sic_code, `sicDescription` AS sic_description_edgar, `stateOfIncorporation` AS state_of_incorporation FROM sec_data.ford_submissions_raw
    UNION ALL
    SELECT cik, 'GM' AS ticker, name AS entity_name, sic AS sic_code, `sicDescription` AS sic_description_edgar, `stateOfIncorporation` AS state_of_incorporation FROM sec_data.gm_submissions_raw
    UNION ALL
    SELECT cik, 'TSLA' AS ticker, name AS entity_name, sic AS sic_code, `sicDescription` AS sic_description_edgar, `stateOfIncorporation` AS state_of_incorporation FROM sec_data.tesla_submissions_raw
) s
LEFT JOIN company_dns.sic_codes_v4_compat_table r
    ON s.sic_code = r.sic_code;
